css:
.loader {
  position: relative;
  width: 50px;
  height: 40px;
  background: repeating-linear-gradient(90deg, #6366f1 0 3px, transparent 3px 5px, #6366f1 5px 6px, transparent 6px 9px, #6366f1 9px 12px, transparent 12px 14px);
}
.loader i {
  position: absolute;
  top: -3px;
  bottom: -3px;
  left: 0;
  width: 3px;
  background: #4338ca;
  box-shadow: 0 0 6px 1px #4338ca;
  animation: sweep 1.4s ease-in-out infinite;
}
@keyframes sweep {
  0% { left: 0; }
  50% { left: calc(100% - 3px); }
  100% { left: 0; }
}
